describe('File Download - Previously Uploaded File', () => {
  const testFilePath = 'cypress/fixtures/test-document.pdf';
  const downloadFolder = Cypress.config('downloadsFolder');
  const fileName = 'test-document.pdf';

  beforeEach(() => {
    cy.visit('/dashboard');
    cy.login('testuser@example.com', 'password123');
    cy.wait(1000);
  });

  it('should successfully download a previously uploaded file', () => {
    cy.get('[data-testid="files-section"]').should('be.visible');
    cy.get('[data-testid="file-list-item"]').first().should('exist');

    cy.get('[data-testid="file-list-item"]')
      .first()
      .within(() => {
        cy.get('[data-testid="download-button"]').click();
      });

    cy.readFile(`${downloadFolder}/${fileName}`).should('exist');

    cy.get('[data-testid="download-success-toast"]')
      .should('be.visible')
      .and('contain', 'File downloaded successfully');
  });

  it('should handle download of file with special characters in name', () => {
    const specialFileName = 'test-file_2024 (1).pdf';

    cy.get('[data-testid="file-list-item"]')
      .contains(specialFileName)
      .parent()
      .within(() => {
        cy.get('[data-testid="download-button"]').click();
      });

    cy.readFile(`${downloadFolder}/${specialFileName}`).should('exist');

    cy.get('[data-testid="download-success-toast"]').should('be.visible');
  });

  it('should show error when download fails', () => {
    cy.intercept('GET', '**/api/files/*/download', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    });

    cy.get('[data-testid="file-list-item"]').first().within(() => {
      cy.get('[data-testid="download-button"]').click();
    });

    cy.get('[data-testid="download-error-toast"]')
      .should('be.visible')
      .and('contain', 'Failed to download file');
  });

  it('should disable download button for files still being processed', () => {
    cy.get('[data-testid="file-list-item"]')
      .filter(':has([data-testid="processing-badge"])')
      .first()
      .within(() => {
        cy.get('[data-testid="download-button"]')
          .should('be.disabled')
          .and('have.attr', 'aria-disabled', 'true');
      });
  });

  it('should maintain file integrity after download', () => {
    const expectedFileSize = 1024;

    cy.get('[data-testid="file-list-item"]').first().within(() => {
      cy.get('[data-testid="file-size"]').invoke('text').as('originalSize');
      cy.get('[data-testid="download-button"]').click();
    });

    cy.readFile(`${downloadFolder}/${fileName}`, 'binary').then((fileContent) => {
      expect(fileContent.length).to.be.greaterThan(0);
    });

    cy.get('@originalSize').then((originalSize) => {
      cy.readFile(`${downloadFolder}/${fileName}`, 'binary').then((fileContent) => {
        expect(fileContent.length.toString()).to.include(originalSize.trim().split(' ')[0]);
      });
    });
  });
});
